function exportArguments(args) {
  const {values,positionals}=parseArgs({args,allowPositionals:true,options:{
    tag:{type:'string',short:'t',multiple:true,default:['general']},
    format:{type:'string',short:'f',default:'json'},color:{type:'boolean',default:true}
