const test = require('node:test');
const assert = require('node:assert/strict');
const app = require('../lib/export-arguments.cjs');
test('defaults, repeated options, negation, and terminator', () => {
  for(const [args,expected] of [
    [[],{tag:['general'],format:'json',color:true,files:[]}],
    [['--no-color','a.csv'],{tag:['general'],format:'json',color:false,files:['a.csv']}],
    [['-t','north','--tag=south','-f','csv','--format=json','--no-color','--color','a.csv'],
      {tag:['north','south'],format:'json',color:true,files:['a.csv']}],
    [['--color','--no-color','--','--tag','-f'],{tag:['general'],format:'json',color:false,files:['--tag','-f']}],
    [['--tag=','--format='],{tag:[''],format:'',color:true,files:[]}]
  ]) {
    const before=[...args]; assert.deepEqual(app.exportArguments(args),expected); assert.deepEqual(args,before);
  }
});
test('strict parsing rejects unknown options and absent string values', () => {
  for(const args of [['--unknown'],['--tag'],['--format'],['--color=yes']])
    assert.throws(()=>app.exportArguments(args));
});

