const test = require('node:test');
const assert = require('node:assert/strict');
const { exportArguments } = require('../lib/export-arguments.cjs');
test('caller format fallback never replaces an explicit value', () => {
  assert.deepEqual(exportArguments(['--no-color','file.csv'], 'csv'),
    {tag:['general'],format:'csv',color:false,files:['file.csv']});
  assert.equal(exportArguments([], '').format, '');
  assert.equal(exportArguments(['--format='], 'csv').format, '');
  assert.equal(exportArguments(['-f','csv','--format=json'], 'xml').format, 'json');
  const args = ['-t','north','--color'];
  assert.deepEqual(exportArguments(args, 'tsv'),
    {tag:['north'],format:'tsv',color:true,files:[]});
  assert.deepEqual(args, ['-t','north','--color']);
});

